(2150267, 294899, 45672, '<td valign="top">Very very nice shot.  My only criticism is the horizon is slightly sloped L to R.  Nice pic.</td>', 'Very very nice shot.  My only criticism is the horizon is slightly sloped L to R.  Nice pic.', '2006-02-14 16:31:29.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2150273, 294882, 34481, '<td valign="top">I love the subtlety of texture and color.  Bold entry.  Good luck.</td>', 'I love the subtlety of texture and color.  Bold entry.  Good luck.', '2006-02-14 16:33:32.000000', NULL, 1),
(2150275, 294594, 45672, '<td valign="top">I think you needed to back up and take this picture.  By cutting of the top of the horses head, it sort of ruins this picture in my opinion.</td>', 'I think you needed to back up and take this picture.  By cutting of the top of the horses head, it sort of ruins this picture in my opinion.', '2006-02-14 16:35:19.000000', NULL, 1),
(2150280, 294582, 45672, '<td valign="top">This one is very nice.  One of the best I''ve seen so far.  Great lighting, contrast and composition.</td>', 'This one is very nice.  One of the best I''ve seen so far.  Great lighting, contrast and composition.', '2006-02-14 16:36:53.000000', NULL, 1),
(2150282, 293045, 34481, '<td valign="top">I love the texture and contrast.  Beautifully composed.  Definitely one of my ribbon picks.  Good luck.</td>', 'I love the texture and contrast.  Beautifully composed.  Definitely one of my ribbon picks.  Good luck.', '2006-02-14 16:37:19.000000', NULL, 1),
(2150285, 294700, 45672, '<td valign="top">Wow, this one is good.  Very good.  How did it look in color?</td>', 'Wow, this one is good.  Very good.  How did it look in color?', '2006-02-14 16:38:10.000000', NULL, 1),
(2150310, 293793, 30982, '<td valign="top">Doesn''t exactly say "country" to me - could just as well be a backyard in suburbia.  But it''s a very pretty shot - love the single cloud just between the tines of the reed-like plant.</td>', 'Doesn''t exactly say "country" to me - could just as well be a backyard in suburbia.  But it''s a very pretty shot - love the single cloud just between the tines of the reed-like plant.', '2006-02-14 16:51:58.000000', NULL, 1),
(2150312, 294392, 30982, '<td valign="top">Heh!  Love the idea!</td>', 'Heh!  Love the idea!', '2006-02-14 16:52:25.000000', NULL, 1),
(2150315, 294395, 30982, '<td valign="top">Tropical country!</td>', 'Tropical country!', '2006-02-14 16:53:50.000000', NULL, 1),
(2150319, 294966, 30982, '<td valign="top">Looks a lot like a shot I took at my grandpa''s farm 30 years ago!  A bit soft but I like the subject and the use of the tree at the top to frame it.</td>', 'Looks a lot like a shot I took at my grandpa''s farm 30 years ago!  A bit soft but I like the subject and the use of the tree at the top to frame it.', '2006-02-14 16:54:33.000000', NULL, 1),
(2150320, 294534, 30982, '<td valign="top">Lovely.  Definitely meets the challenge, and then some.  The contrast of textures and the lighting is wonderful!</td>', 'Lovely.  Definitely meets the challenge, and then some.  The contrast of textures and the lighting is wonderful!', '2006-02-14 16:55:25.000000', NULL, 1),
(2150380, 294965, 3087, '<td valign="top">I like big skies, especially when the sky is more interesting than the foreground and I''m definitely NOT a stickler for rule of thirds on this front but I do think the crop at the bottom feels a touch tight, a touch severe, a bit hemmed in. (I sound like a frigging thesaurus)<br/> <br/>I like the subject matter and the light too.... nice and even. <br/> <br/>The scene doesn''t grab me particularly, so in that sense, I find it a little underwhelming or maybe just find the content boring.<br/> <br/>But it is nicely exposed and nice light.</td>', 'I like big skies, especially when the sky is more interesting than the foreground and I''m definitely NOT a stickler for rule of thirds on this front but I do think the crop at the bottom feels a touch tight, a touch severe, a bit hemmed in. (I sound like a frigging thesaurus) I like the subject matter and the light too.... nice and even.  The scene doesn''t grab me particularly, so in that sense, I find it a little underwhelming or maybe just find the content boring. But it is nicely exposed and nice light.', '2006-02-14 17:27:43.000000', NULL, 1),
(2150387, 293291, 3087, '<td valign="top">Wow! Beautiful lighting and wonderful perspective, great composition, nice sky, everything works!!!</td>', 'Wow! Beautiful lighting and wonderful perspective, great composition, nice sky, everything works!!!', '2006-02-14 17:30:58.000000', NULL, 1),
(2150392, 294904, 21034, '<td valign="top">I like the subject and framing, but the flat light doesn''t do much for me.</td>', 'I like the subject and framing, but the flat light doesn''t do much for me.', '2006-02-14 17:32:14.000000', NULL, 1),
