(2150791, 294661, 30982, '<td valign="top">Heh!  Good for a chuckle!  Great perspective - hope you kept the lens just far enough away!</td>', 'Heh!  Good for a chuckle!  Great perspective - hope you kept the lens just far enough away!', '2006-02-14 20:56:34.000000', NULL, 1),
(2150793, 294700, 30982, '<td valign="top">I like the composition and the structures chosen.  Not sure about the hue though.</td>', 'I like the composition and the structures chosen.  Not sure about the hue though.', '2006-02-14 20:57:18.000000', NULL, 1),
(2150794, 293910, 30982, '<td valign="top">Very good duck picture, but doesn''t scream "country life".</td>', 'Very good duck picture, but doesn''t scream "country life".', '2006-02-14 20:57:52.000000', NULL, 1),
(2150796, 292218, 30982, '<td valign="top">Love the "personalities" on display here!</td>', 'Love the "personalities" on display here!', '2006-02-14 20:58:29.000000', NULL, 1),
