(2160757, 294836, 38032, '<td valign="top">I like this - the composition is really good except for maybe the chopped of bottom cow but I realize this is a captured moment so it can be difficult to move your subjects ... Anyway - very nice ... the photo does have an old/noisy/desaturated  look to it which could be seen as a positive or negative. 7</td>', 'I like this - the composition is really good except for maybe the chopped of bottom cow but I realize this is a captured moment so it can be difficult to move your subjects ... Anyway - very nice ... the photo does have an old/noisy/desaturated  look to it which could be seen as a positive or negative. 7', '2006-02-18 08:43:31.000000', NULL, 1),
(2160776, 293900, 50346, '<td valign="top">Nicely done, way to go!!!</td>', 'Nicely done, way to go!!!', '2006-02-18 09:08:42.000000', NULL, 1),
